"""Summarise calls made by TinyGL functions in an objdump listing."""
import re
import sys
from collections import Counter, defaultdict

path = sys.argv[1]
pattern = re.compile(sys.argv[2]) if len(sys.argv) > 2 else re.compile(
    r"^(gl_|glop|ZB_|zb|glshim_|gl_transform|gl_shade|gl_draw|updateTmp|gl_add|gl_vertex|gl_eval|gl_clip|gl_M4|gl_V3|gl_Matrix|gl_compile|gl_find|gl_get|gl_add_op|glRunTest|gl_spec|specbuf|ZB_)"
)
func_re = re.compile(r"^([0-9a-f]+) <([^>]+)>:")
call_re = re.compile(r"\bcall(?:8|4|12|0|x8)?\s+[0-9a-f]+ <([^>+]+)")
funcs = {}
cur = None
for line in open(path):
    m = func_re.match(line)
    if m:
        cur = m.group(2)
        funcs[cur] = {"addr": int(m.group(1), 16), "n": 0, "calls": Counter(), "ops": Counter()}
        continue
    if cur is None:
        continue
    parts = line.split("\t")
    if len(parts) >= 2 and parts[0].strip().endswith(":"):
        funcs[cur]["n"] += 1
        op = parts[1].strip().split()[0] if parts[1].strip() else ""
        funcs[cur]["ops"][op] += 1
        m = call_re.search(line)
        if m:
            funcs[cur]["calls"][m.group(1)] += 1

for name, f in sorted(funcs.items(), key=lambda kv: kv[1]["addr"]):
    if not pattern.search(name):
        continue
    region = "IRAM" if 0x40370000 <= f["addr"] < 0x403E0000 else ("FLASH" if f["addr"] >= 0x42000000 else hex(f["addr"]))
    helpers = {k: v for k, v in f["calls"].items() if k.startswith("__") or k in ("sqrtf", "powf", "sqrt", "pow", "memcpy", "memset", "floorf", "cosf", "sinf")}
    fp = {k: v for k, v in f["ops"].items() if k.endswith(".s") or k.endswith(".d")}
    print(f"{name:40s} {region:6s} insns={f['n']:5d} helpers={dict(helpers)} fpops={sum(fp.values())} div={fp.get('div0.s',0)}")

"""Resolve callx8 targets (l32r literal loads) in an Xtensa ELF for chosen functions.

usage: callx.py firmware.elf func_regex
"""
import re
import struct
import subprocess
import sys
from collections import Counter, defaultdict

TC = "/Users/rod/build/stopwatch-screensaver/.platformio/packages/toolchain-xtensa-esp32s3/bin/xtensa-esp32s3-elf-"
elf, pat = sys.argv[1], re.compile(sys.argv[2])

syms = {}
for line in subprocess.run([TC + "nm", elf], capture_output=True, text=True).stdout.splitlines():
    p = line.split()
    if len(p) == 3:
        syms.setdefault(int(p[0], 16), p[2])

# section contents for literal lookup
sections = []
hdr = subprocess.run([TC + "objdump", "-h", elf], capture_output=True, text=True).stdout
for line in hdr.splitlines():
    p = line.split()
    if len(p) >= 7 and p[0].isdigit():
        sections.append((p[1], int(p[3], 16), int(p[2], 16), int(p[5], 16)))
data = open(elf, "rb").read()


def word(addr):
    for name, vma, size, off in sections:
        if vma <= addr < vma + size:
            return struct.unpack_from("<I", data, off + addr - vma)[0]
    return None


dis = subprocess.run([TC + "objdump", "-d", "--no-show-raw-insn", elf], capture_output=True, text=True).stdout
func_re = re.compile(r"^([0-9a-f]+) <([^>]+)>:")
cur = None
lits = {}
totals = defaultdict(Counter)
for line in dis.splitlines():
    m = func_re.match(line)
    if m:
        cur = m.group(2) if pat.search(m.group(2)) else None
        lits = {}
        continue
    if not cur:
        continue
    m = re.search(r"l32r\s+(a\d+), ([0-9a-f]+)", line)
    if m:
        lits[m.group(1)] = word(int(m.group(2), 16))
        continue
    m = re.search(r"callx8\s+(a\d+)", line)
    if m:
        v = lits.get(m.group(1))
        totals[cur][syms.get(v, hex(v) if v else "?")] += 1
for f, c in totals.items():
    print(f, dict(c))

