__attribute__((destructor, no_instrument_function)) static void dump(void) {
  const char *path = getenv("PROFILE_OUT");
  if (!path) return;
  FILE *f = fopen(path, "w");
  fprintf(f, "main %p\n", (void *)main);
  for (int i = 0; i < SLOTS; i++)
    if (keys[i]) fprintf(f, "%p %lu\n", keys[i], counts[i]);
  fclose(f);
}

