                (unsigned)REG_READ(EXTMEM_DCACHE_AUTOLOAD_SCT0_ADDR_REG),
                (unsigned)REG_READ(EXTMEM_DCACHE_AUTOLOAD_SCT0_SIZE_REG));
}
