void test_a_smooth_line_at_the_canvas_edge_stays_inside_it(void) {
  open_line_scene(1);
  const float e = 1.0f - 0.1f * PIXEL_NDC;
  draw_line(e, -1.2f, e, 1.2f);
  TEST_ASSERT_TRUE(lit_in_column(SIZE - 1) > 0);
